import React, { useCallback, useMemo, useRef, useState } from 'react';
import './App.css';

function sumUpTo(count: number): number {
  let total = 0;
  for (let value = 1; value <= count; value += 1) total += value;
  return total;
}

// Defined outside App so it keeps its identity, and memoized so unrelated parent state skips it.
const ParityBadge = React.memo(function ParityBadge({
  count,
  onReset
}: {
  count: number;
  onReset: () => void;
}) {
  const renders = useRef(0);
  renders.current += 1;

  return (
    <div className="panel">
      <div className="label">Parity</div>
      <div className="v" data-testid="parity">{count % 2 === 0 ? 'even' : 'odd'}</div>
      <div className="hint">Badge renders: <span data-testid="badge-renders">{renders.current}</span></div>
      <button className="btn ghost badge-reset" onClick={onReset}>Reset from badge</button>
    </div>
  );
});

export default function App() {
  const [count, setCount] = useState(0);
  const [note, setNote] = useState('');

  const renders = useRef(0);
  renders.current += 1;

  const sumRuns = useRef(0);
  const sum = useMemo(() => {
    sumRuns.current += 1;
    return sumUpTo(count);
  }, [count]);

  const reset = useCallback(() => setCount(0), []);
  const increment = () => setCount((c) => c + 1);

  // Each update reads the latest value, so none of them is lost.
  const addFive = () => {
    for (let step = 0; step < 5; step += 1) setCount((c) => c + 1);
  };

  const addLater = () => {
    window.setTimeout(() => {
      setCount((c) => c + 1);
      setCount((c) => c + 1);
    }, 200);
  };

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Debug Extra Renders</h1>
        <p className="subtitle">Each render here has a reason.</p>

        <div className="stats">
          <div className="stat">
            <div className="k">Count</div>
            <div className="v" data-testid="count">{count}</div>
          </div>
          <div className="stat">
            <div className="k">Renders</div>
            <div className="v" data-testid="renders">{renders.current}</div>
          </div>
          <div className="stat">
            <div className="k">Sum</div>
            <div className="v" data-testid="sum">{sum}</div>
          </div>
          <div className="stat">
            <div className="k">Sum runs</div>
            <div className="v" data-testid="sum-runs">{sumRuns.current}</div>
          </div>
        </div>

        <div className="actions">
          <button className="btn" onClick={increment}>Increment</button>
          <button className="btn ghost" onClick={reset}>Reset</button>
          <button className="btn ghost add-five" onClick={addFive}>Add 5</button>
          <button className="btn ghost add-later" onClick={addLater}>Add 2 later</button>
        </div>

        <ParityBadge count={count} onReset={reset} />

        <div className="panel">
          <label className="label" htmlFor="note">Note</label>
          <input
            id="note"
            className="note-input"
            value={note}
            onChange={(event) => setNote(event.target.value)}
          />
          <div className="hint">Saved note: <span data-testid="note">{note}</span></div>
        </div>
      </section>
    </main>
  );
}

